 namespace hardness; global $g; if (!isset($g['conteudo']['jsTexto'])) { goto xFVNJ; } $g['conteudo']['jsTexto'] .= <<<'JS'
(function ($) {
	if (!$ || window.__hardnessCsvExportFeedback) {
		return;
	}
	window.__hardnessCsvExportFeedback = true;
	var waitingForCsvSelectionDialog = false;
	var csvSelectionDialogTimer = null;
	var exportDialogWidth = 520;
	var exportDialogContentHeight = 420;

	function isCsvExport(settings) {
		var data = settings && settings.data ? settings.data : '';
		if (typeof data !== 'string') {
			// O handler ajaxSend recebe todas as requisições. Objetos nativos como FormData não podem ser processados pelo $.param do jQuery 1.6.2, pois seus métodos seriam chamados sem o contexto correto.
			if (!$.isPlainObject(data) && !$.isArray(data)) {
				return false;
			}
			data = $.param(data);
		}
		return data.indexOf('generateCSV=true') !== -1;
	}

	function getExportDialog() {
		var $dialogs = $('.ui-dialog:visible');
		return $dialogs.filter(function () {
			return $(this).find('.ui-dialog-buttonpane button').filter(function () {
				return $.trim($(this).text()) === 'Imprimir';
			}).length > 0;
		}).last();
	}

	function isExportSelectionDialog($dialog) {
		var $content = $dialog.children('.ui-dialog-content').first();
		var hasPrintButton = $dialog.find('.ui-dialog-buttonpane button').filter(function () {
			return $.trim($(this).text()) === 'Imprimir' || $.trim($(this).text()) === 'Gerando CSV...';
		}).length > 0;
		return hasPrintButton && $content.find('form table input[type="checkbox"]').length > 0;
	}

	function fitExportSelectionDialog($dialog) {
		if (!$dialog.length || !isExportSelectionDialog($dialog)) {
			return;
		}

		var $content = $dialog.children('.ui-dialog-content').first();
		if (!$content.length) {
			return;
		}

		var availableWidth = Math.max(280, $(window).width() - 32);
		var availableHeight = Math.max(180, $(window).height() - 180);
		var targetWidth = Math.min(exportDialogWidth, availableWidth);
		var targetHeight = Math.min(exportDialogContentHeight, availableHeight);

		$dialog.addClass('hardnessExportSelectionDialog').css('width', targetWidth + 'px');
		$content.css({
			height: targetHeight + 'px',
			maxHeight: targetHeight + 'px',
			overflowY: 'auto',
			overflowX: 'auto'
		});

		$dialog.css({
			left: ($(window).scrollLeft() + Math.max(16, Math.round(($(window).width() - $dialog.outerWidth()) / 2))) + 'px',
			top: ($(window).scrollTop() + Math.max(16, Math.round(($(window).height() - $dialog.outerHeight()) / 2))) + 'px'
		});
	}

	function installExportSelectionDialogFit() {
		if (typeof window.acoesGridImpHtml !== 'function' || window.acoesGridImpHtml.__hardnessDialogFit) {
			return;
		}

		var originalAcoesGridImpHtml = window.acoesGridImpHtml;
		window.acoesGridImpHtml = function () {
			var result = originalAcoesGridImpHtml.apply(this, arguments);
			var $dialog = $('.ui-dialog:visible').last();
			addSelectionButtons($dialog);
			fitExportSelectionDialog($dialog);
			return result;
		};
		window.acoesGridImpHtml.__hardnessDialogFit = true;
	}

	function beginExport($dialog) {
		if (!$dialog.length) {
			return;
		}
		var $buttons = $dialog.find('.ui-dialog-buttonpane button');
		var $print = $buttons.filter(function () {
			return $.trim($(this).text()) === 'Imprimir';
		});
		if (!$print.length) {
			return;
		}
		$buttons.prop('disabled', true).addClass('ui-state-disabled');
		$print.data('csvExportOriginalText', $print.text()).text('Gerando CSV...');
		if (!$dialog.find('.csvExportStatus').length) {
			$('<div class="csvExportStatus ui-state-highlight ui-corner-all" style="margin:8px 6px;padding:8px;line-height:18px;">' +
				'<span class="ui-icon ui-icon-clock" style="float:left;margin-right:6px;"></span>' +
				'<b>Gerando CSV...</b> O download iniciará automaticamente. Não feche esta janela.' +
				'</div>').insertBefore($dialog.find('.ui-dialog-buttonpane'));
		}
	}

	function endExport($dialog) {
		if (!$dialog || !$dialog.length) {
			return;
		}
		$dialog.find('.csvExportStatus').remove();
		$dialog.find('.ui-dialog-buttonpane button').prop('disabled', false).removeClass('ui-state-disabled');
		$dialog.find('.ui-dialog-buttonpane button').filter(function () {
			return $.trim($(this).text()) === 'Gerando CSV...';
		}).each(function () {
			$(this).text($(this).data('csvExportOriginalText') || 'Imprimir');
		});
	}

	function addSelectionButtons($targetDialog) {
		var hasTargetDialog = $targetDialog && $targetDialog.length;
		if (!hasTargetDialog && !waitingForCsvSelectionDialog) {
			return;
		}
		var $dialog = hasTargetDialog ? $targetDialog : $('.ui-dialog:visible').filter(function () {
			var $this = $(this);
			return $this.find('.ui-dialog-buttonpane button').filter(function () {
				return $.trim($(this).text()) === 'Imprimir';
			}).length > 0 && $this.find('input[type="checkbox"]').length > 0;
		}).last();
		if (!$dialog.length || !isExportSelectionDialog($dialog) || $dialog.find('.csvSelectionActions').length) {
			return;
		}

		var $actions = $('<span class="csvSelectionActions"></span>');
		$('<button type="button">Marcar todos</button>').click(function () {
			$dialog.children('.ui-dialog-content').find('form table input[type="checkbox"]:not(:disabled)').prop('checked', true);
			return false;
		}).appendTo($actions);
		$('<button type="button">Desmarcar todos</button>').click(function () {
			$dialog.children('.ui-dialog-content').find('form table input[type="checkbox"]:not(:disabled)').prop('checked', false);
			return false;
		}).appendTo($actions);
		$actions.find('button').button();
		$dialog.find('.ui-dialog-buttonpane').prepend($actions);
		waitingForCsvSelectionDialog = false;
	}

	function csvSelectionDialogRequested(event) {
		var $action = $(event.target).closest('a,button');
		if ($.trim($action.text()) !== 'Gerar CSV (Excel)') {
			return;
		}
		waitingForCsvSelectionDialog = true;
		window.clearTimeout(csvSelectionDialogTimer);
		csvSelectionDialogTimer = window.setTimeout(function () {
			waitingForCsvSelectionDialog = false;
		}, 2000);
		window.setTimeout(addSelectionButtons, 0);
	}

	if (document.addEventListener) {
		document.addEventListener('click', csvSelectionDialogRequested, true);
	} else {
		$(document).delegate('a', 'click', csvSelectionDialogRequested);
	}

	if (window.MutationObserver && document.body) {
		new MutationObserver(function () {
			addSelectionButtons();
		}).observe(document.body, { childList: true, subtree: true });
	} else {
		window.setInterval(addSelectionButtons, 500);
	}
	addSelectionButtons();
	installExportSelectionDialogFit();
	$(window).unbind('resize.hardnessExportSelectionDialog').bind('resize.hardnessExportSelectionDialog', function () {
		fitExportSelectionDialog($('.hardnessExportSelectionDialog:visible').last());
	});

	$(document).ajaxSend(function (event, xhr, settings) {
		if (!isCsvExport(settings)) {
			return;
		}
		var $dialog = getExportDialog();
		xhr.__hardnessCsvExportDialog = $dialog;
		beginExport($dialog);
	});

	$(document).ajaxComplete(function (event, xhr, settings) {
		if (isCsvExport(settings)) {
			endExport(xhr.__hardnessCsvExportDialog);
		}
	});
}(jQuery));
