                                            } else {
                                                return '';
                                            }
                                        }
                                    },
                                    legend: {
                                        show: {$incluirGraficoLegend_},
                                        position: "ne",
                                        backgroundColor: "#D2E8FF"
                                    }
                                });
                            })(document.getElementById("grafico{$g['divId']}"));
                        }
