&nbsp;&nbsp;&nbsp;&nbsp;<span style="font-family: courier;">!BUSCA1</span><br />
&nbsp;&nbsp;&nbsp;&nbsp;<span style="font-family: courier;">!BUSCA1;!BUSCA2</span><br />
&nbsp;&nbsp;&nbsp;&nbsp;<span style="font-family: courier;">!"BUSCA1 BUSCA2"</span><br />
